args.ReplacementContent:
.candle-glow {
  animation: candleFlicker 3.5s infinite ease-in-out;
}

/* Floating animation for Hunter */
@keyframes float {
  0%,
  100% {
    transform: translateY(0px);
  }
  50% {
    transform: translateY(-10px);
  }
}

.float-animation {
  animation: float 7s ease-in-out infinite;
}

/* Hero Visual Identity Art */
.hero-art {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 520px;
}

.hunter-art {
  width: min(100%, 480px);
  max-height: 72vh;
  object-fit: contain;
  filter: drop-shadow(0 14px 45px rgba(0, 0, 0, 0.85)) drop-shadow(0 0 35px rgba(197, 160, 89, 0.2));
  animation: float 7s ease-in-out infinite;
  position: relative;
  z-index: 3;
}

.hero-book {
  position: absolute;
  width: min(44vw, 460px);
  right: -2%;
