import React, { useState, useEffect } from "react";

export interface NavigationProps {
  currentRoute: string;
  onRouteChange: (route: string, params?: Record<string, string>) => void;
  onOpenDemoModal?: () => void;
  onOpenAuthModal?: (mode: "signin" | "signup") => void;
}

export const TopBar: React.FC<NavigationProps> = ({
  currentRoute,
  onRouteChange,
  onOpenDemoModal,
  onOpenAuthModal,
}) => {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  // Primary navigation items according to specification: Home, Dashboard, Archive, Integrations, Safety
  const primaryNavItems = [
    { id: "landing", label: "Home", href: "#/" },
    { id: "dashboard", label: "Dashboard", href: "#/dashboard" },
    { id: "archive", label: "Archive", href: "#/archive" },
    { id: "integrations", label: "Integrations", href: "#/integrations" },
    { id: "safety", label: "Safety", href: "#/safety" },
  ];

  const isItemActive = (id: string): boolean => {
    if (id === "landing") {
      return currentRoute === "landing" || currentRoute === "" || currentRoute === "home";
    }
    if (id === "safety") {
      return currentRoute === "safety" || currentRoute === "about";
    }
    if (id === "archive") {
      return currentRoute === "archive" || currentRoute === "chambers";
    }
    return currentRoute === id;
  };

  const handleNav = (id: string) => {
    onRouteChange(id);
    setMobileMenuOpen(false);
  };

  // Close mobile drawer on Escape key
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && mobileMenuOpen) {
        setMobileMenuOpen(false);
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [mobileMenuOpen]);

  return (
    <header
      style={{
        height: "86px",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        gap: "16px",
        padding: "10px clamp(16px, 3vw, 42px)",
        borderBottom: "1px solid rgba(197, 160, 89, 0.35)",
        background: "linear-gradient(180deg, rgba(13, 13, 17, 0.96), rgba(8, 8, 10, 0.98))",
        position: "sticky",
        top: 0,
        zIndex: 50,
        backdropFilter: "blur(14px)",
      }}
    >
      {/* Brand logo + Title: Clickable from every page navigating to #/ */}
      <a
        href="#/"
        id="topbar-brand-link"
        onClick={(e) => {
          e.preventDefault();
          handleNav("landing");
        }}
        aria-label="Keys of the Departed sanctuary home"
        style={{
          display: "flex",
          alignItems: "center",
          gap: "12px",
          cursor: "pointer",
          minWidth: "250px",
          textDecoration: "none",
        }}
      >
        <img
          src="/logo.png"
          alt="Keys of the Departed emblem"
          style={{
            width: "50px",
            height: "54px",
            objectFit: "contain",
            filter: "drop-shadow(0 0 10px rgba(197, 160, 89, 0.35))",
          }}
        />
        <div>
          <div
            className="display"
            style={{
              fontSize: "17px",
              fontWeight: 700,
              letterSpacing: "0.06em",
              color: "#f7ebd2",
              textShadow: "0 2px 4px rgba(0,0,0,0.9)",
              lineHeight: 1.1,
            }}
          >
            KEYS OF THE DEPARTED
          </div>
          <div
            className="serif"
            style={{
              fontSize: "12px",
              fontStyle: "italic",
              color: "#c7b591",
              marginTop: "2px",
            }}
          >
            Machine Identity Investigation
          </div>
        </div>
      </a>

      {/* Primary Desktop Navigation Links: Home, Dashboard, Archive, Integrations, Safety */}
      <nav
        className="desktop-nav"
        aria-label="Primary sanctuary navigation"
        style={{ display: "flex", alignItems: "center", gap: "6px" }}
      >
        {primaryNavItems.map((item) => {
          const isActive = isItemActive(item.id);
          return (
            <a
              key={item.id}
              href={item.href}
              id={`nav-link-${item.id}`}
              onClick={(e) => {
                e.preventDefault();
                handleNav(item.id);
              }}
              className="display"
              aria-current={isActive ? "page" : undefined}
              style={{
                textDecoration: "none",
                display: "inline-block",
                borderBottom: isActive ? "2px solid var(--gold)" : "2px solid transparent",
                color: isActive ? "var(--gold2)" : "#c8b994",
                padding: "8px 14px",
                fontSize: "12px",
                fontWeight: 600,
                letterSpacing: "0.08em",
                textTransform: "uppercase",
                cursor: "pointer",
                transition: "all 0.2s ease",
              }}
            >
              {item.label}
            </a>
          );
        })}
      </nav>

      {/* Right Secondary Actions: Demo Tour, Sign In, Sign Up */}
      <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
        {onOpenDemoModal && (
          <button
            onClick={onOpenDemoModal}
            className="btn small"
            id="topbar-btn-demo"
            style={{
              background: "linear-gradient(180deg, #8b1e2d, #521019)",
              borderColor: "var(--gold)",
              boxShadow: "0 0 14px rgba(139, 30, 45, 0.4)",
              whiteSpace: "nowrap",
            }}
          >
            ✦ Demo Tour
          </button>
        )}

        <button
          onClick={() => {
            if (onOpenAuthModal) onOpenAuthModal("signin");
            else handleNav("auth");
          }}
          className="btn ghost small desktop-auth"
          id="topbar-btn-signin"
          style={{
            textTransform: "uppercase",
            borderColor:
              currentRoute === "auth" || currentRoute === "signin" ? "var(--gold)" : undefined,
            color:
              currentRoute === "auth" || currentRoute === "signin" ? "var(--cream)" : undefined,
          }}
        >
          Sign In
        </button>

        <button
          onClick={() => {
            if (onOpenAuthModal) onOpenAuthModal("signup");
            else handleNav("signup");
          }}
          className="btn small secondary desktop-auth"
          id="topbar-btn-signup"
          style={{ textTransform: "uppercase", fontSize: "10px" }}
        >
          Sign Up
        </button>

        {/* Mobile Hamburger Button */}
        <button
          className="mobile-toggle"
          id="topbar-mobile-toggle"
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          aria-label={mobileMenuOpen ? "Close navigation menu" : "Open navigation menu"}
          aria-expanded={mobileMenuOpen}
          aria-controls="mobile-navigation-drawer"
          style={{
            background: "transparent",
            border: "1px solid var(--line)",
            color: "var(--gold2)",
            padding: "8px 12px",
            fontSize: "18px",
            cursor: "pointer",
            borderRadius: "3px",
            display: "none",
          }}
        >
          {mobileMenuOpen ? "✕" : "☰"}
        </button>
      </div>

      {/* Mobile Drawer Menu */}
      {mobileMenuOpen && (
        <div
          id="mobile-navigation-drawer"
          role="dialog"
          aria-modal="true"
          aria-label="Sanctuary navigation drawer"
          style={{
            position: "absolute",
            top: "86px",
            left: 0,
            right: 0,
            background: "rgba(13, 13, 17, 0.98)",
            borderBottom: "1px solid var(--gold)",
            padding: "20px 24px 28px",
            display: "flex",
            flexDirection: "column",
            gap: "10px",
            zIndex: 100,
            backdropFilter: "blur(16px)",
            boxShadow: "0 20px 40px rgba(0,0,0,0.8)",
          }}
        >
          <div
            className="eyebrow"
            style={{ color: "var(--gold)", fontSize: "10px", marginBottom: "4px" }}
          >
            SANCTUARY NAVIGATION
          </div>
          {primaryNavItems.map((item) => {
            const isActive = isItemActive(item.id);
            return (
              <a
                key={item.id}
                href={item.href}
                id={`mobile-nav-link-${item.id}`}
                onClick={(e) => {
                  e.preventDefault();
                  handleNav(item.id);
                }}
                className="display"
                aria-current={isActive ? "page" : undefined}
                style={{
                  textDecoration: "none",
                  display: "block",
                  color: isActive ? "var(--gold2)" : "#c8b994",
                  padding: "12px 8px",
                  fontSize: "13.5px",
                  cursor: "pointer",
                  borderBottom: "1px solid rgba(197, 160, 89, 0.15)",
                }}
              >
                {item.label}
              </a>
            );
          })}

          <div style={{ display: "flex", gap: "10px", marginTop: "16px" }}>
            <button
              onClick={() => {
                setMobileMenuOpen(false);
                if (onOpenAuthModal) onOpenAuthModal("signin");
                else handleNav("auth");
              }}
              className="btn ghost small"
              style={{ flex: 1 }}
            >
              Sign In
            </button>
            <button
              onClick={() => {
                setMobileMenuOpen(false);
                if (onOpenAuthModal) onOpenAuthModal("signup");
                else handleNav("signup");
              }}
              className="btn small"
              style={{ flex: 1 }}
            >
              Sign Up
            </button>
          </div>
        </div>
      )}

      {/* Responsive Breakpoints CSS */}
      <style>{`
        @media (max-width: 900px) {
          .desktop-nav {
            display: none !important;
          }
          .desktop-auth {
            display: none !important;
          }
          .mobile-toggle {
            display: block !important;
          }
        }
      `}</style>
    </header>
  );
};

import React, { useState } from "react";

export interface FourChambersPreviewProps {
  onSelectChamber: (chamber: "LOST" | "FORGOTTEN" | "LONELY" | "INNOCENT") => void;
  title?: string;
  subtitle?: string;
}

export const CHAMBER_DEFINITIONS = [
  {
    name: "LOST" as const,
    glyph: "/glyph-lost.png",
    subtitle: "Departed Owner",
    color: "#c49a52",
    glowColor: "rgba(197, 160, 89, 0.6)",
    shortDescription: "Owner departed; active machine access remains unmanaged.",
  },
  {
    name: "FORGOTTEN" as const,
    glyph: "/glyph-forgotten.png",
    subtitle: "Missing Provenance",
    color: "#a52c30",
    glowColor: "rgba(165, 44, 48, 0.65)",
    shortDescription: "Zero human signatures or tickets found in historical audit logs.",
  },
  {
    name: "LONELY" as const,
    glyph: "/glyph-lonely.png",
    subtitle: "Dormant Privilege",
    color: "#d4a853",
    glowColor: "rgba(212, 168, 83, 0.6)",
    shortDescription: "Owner active, but key credentials dormant over 90 days.",
  },
  {
    name: "INNOCENT" as const,
    glyph: "/glyph-innocent.png",
    subtitle: "Unexpiring Hotfix",
    color: "#7e9272",
    glowColor: "rgba(126, 146, 114, 0.65)",
    shortDescription: "Emergency release key left active without automated expiration.",
  },
];

export const FourChambersPreview: React.FC<FourChambersPreviewProps> = ({
  onSelectChamber,
  title = "THE FOUR CHAMBERS",
  subtitle = "Every forgotten machine identity falls into one of four archetypal chambers.",
}) => {
  const [activeChamber, setActiveChamber] = useState<string | null>(null);

  return (
    <div style={{ width: "100%" }}>
      {(title || subtitle) && (
        <div style={{ textAlign: "center", marginBottom: "40px" }}>
          {title && (
            <div
              className="eyebrow"
              style={{ color: "var(--gold)", letterSpacing: "0.2em", marginBottom: "8px" }}
            >
              ✦ {title} ✦
            </div>
          )}
          {subtitle && (
            <p
              className="serif"
              style={{
                fontSize: "19px",
                color: "#c7b591",
                maxWidth: "600px",
                margin: "0 auto",
                fontStyle: "italic",
                lineHeight: 1.5,
              }}
            >
              {subtitle}
            </p>
          )}
        </div>
      )}

      {/* Four evenly spaced illustrations directly against page background — NO CARDS */}
      <div className="chambers-direct-grid">
        {CHAMBER_DEFINITIONS.map((ch) => {
          const isHovered = activeChamber === ch.name;

          return (
            <div
              key={ch.name}
              role="button"
              tabIndex={0}
              id={`chamber-preview-${ch.name.toLowerCase()}`}
              aria-label={`Inspect ${ch.name} chamber: ${ch.subtitle}`}
              onClick={() => onSelectChamber(ch.name)}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  onSelectChamber(ch.name);
                }
              }}
              onMouseEnter={() => setActiveChamber(ch.name)}
              onMouseLeave={() => setActiveChamber(null)}
              onFocus={() => setActiveChamber(ch.name)}
              onBlur={() => setActiveChamber(null)}
              style={{
                background: "transparent",
                border: "none",
                outline: "none",
                cursor: "pointer",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                textAlign: "center",
                padding: "16px 12px",
                transition: "transform 0.3s cubic-bezier(0.16, 1, 0.3, 1)",
              }}
            >
              {/* Glyph Illustration */}
              <div
                style={{
                  position: "relative",
                  width: "104px",
                  height: "104px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  marginBottom: "14px",
                }}
              >
                <img
                  src={ch.glyph}
                  alt={ch.name}
                  style={{
                    width: "96px",
                    height: "96px",
                    objectFit: "contain",
                    filter: isHovered
                      ? `drop-shadow(0 0 20px ${ch.glowColor}) drop-shadow(0 4px 12px rgba(0,0,0,0.8))`
                      : "drop-shadow(0 6px 14px rgba(0,0,0,0.75))",
                    transform: isHovered ? "translateY(-6px) scale(1.06)" : "translateY(0) scale(1)",
                    transition: "transform 0.3s ease, filter 0.3s ease",
                  }}
                />
              </div>

              {/* Small, Elegant Label */}
              <div
                className="display"
                style={{
                  fontSize: "16px",
                  fontWeight: 700,
                  letterSpacing: "0.14em",
                  color: isHovered ? "var(--gold2)" : "#eedab8",
                  textTransform: "uppercase",
                  transition: "color 0.25s ease",
                  marginBottom: "4px",
                }}
              >
                {ch.name}
              </div>

              {/* Subtitle */}
              <div
                className="serif"
                style={{
                  fontSize: "13px",
                  color: isHovered ? ch.color : "var(--muted)",
                  fontStyle: "italic",
                  marginBottom: "8px",
                  transition: "color 0.25s ease",
                }}
              >
                {ch.subtitle}
              </div>

              {/* Short description revealed on interaction (hover/focus) */}
              <div
                style={{
                  fontSize: "12px",
                  lineHeight: 1.45,
                  color: "#dcd0b8",
                  maxWidth: "200px",
                  opacity: isHovered ? 1 : 0,
                  maxHeight: isHovered ? "60px" : "0px",
                  overflow: "hidden",
                  transition: "opacity 0.25s ease, max-height 0.25s ease",
                  pointerEvents: "none",
                }}
              >
                {ch.shortDescription}
              </div>

              <div
                style={{
                  fontSize: "10px",
                  fontFamily: "var(--mono)",
                  letterSpacing: "0.1em",
                  color: isHovered ? "var(--gold)" : "transparent",
                  marginTop: "6px",
                  transition: "color 0.2s ease",
                  textTransform: "uppercase",
                }}
              >
                Inspect Archive →
              </div>
            </div>
          );
        })}
      </div>

      <style>{`
        .chambers-direct-grid {
          display: grid;
          grid-template-columns: repeat(4, 1fr);
          gap: 24px;
          max-width: 1040px;
          margin: 0 auto;
        }
        @media (max-width: 860px) {
          .chambers-direct-grid {
            grid-template-columns: repeat(2, 1fr);
            gap: 20px;
          }
        }
        @media (max-width: 480px) {
          .chambers-direct-grid {
            grid-template-columns: 1fr;
            gap: 16px;
          }
        }
      `}</style>
    </div>
  );
};

import React from "react";
import { FourChambersPreview } from "../components/FourChambersPreview.js";

export interface LandingPageProps {
  onRouteChange: (route: string, params?: Record<string, string>) => void;
  onOpenDemo: () => void;
}

export const LandingPage: React.FC<LandingPageProps> = ({ onRouteChange, onOpenDemo }) => {
  return (
    <div className="animate-fade-in" style={{ width: "100%", overflowX: "hidden" }}>
      {/* ============================================================== */}
      {/* 1. RESTORED VISUAL HERO: HUNTER, GOLDEN BOOK & GOTHIC DEPTH */}
      {/* ============================================================== */}
